    'wings.loader.tagline': 'భారత్ · 2026',
    'wings.loader.quote': '"మీరు సూర్యుడిలా ప్రకాశించాలనుకుంటే, మొదట సూర్యుడిలా మండాలి." ఆయన ఇలా కూడా అన్నారు, "శ్రేష్ఠత అనేది నిరంతర ప్రక్రియ, ప్రమాదం కాదు."',
    'wings.loader.author': '— ఏ.పి.జె. అబ్దుల్ కలామ్',
    'wings.nav.brand': 'ఇగ్నైట్ యూత్ కమ్యూనిటీ',
