    'wings.subtitle': 'ప్రతి వింగ్ నిర్దిష్ట ప్రతిభ మరియు నైపుణ్యాలను పెంపొందించడానికి రూపొందించబడింది, రేపటి భారత్ కోసం సమగ్ర నాయకులను సృష్టిస్తుంది.',
