    'wings.wing11.requirements': 'वाणिज्य, व्यवसाय आणि आर्थिक साक्षरतेत रुची.',
    'wings.wing11.faq.q': 'प्रश्न: मला वाणिज्य पार्श्वभूमीची गरज आहे का?',
    'wings.wing11.faq.a': 'उत्तर: नाही, फक्त व्यवसाय आणि वित्ताबद्दल उत्सुकता!',
    'wings.wing12.name': 'मानव्यशास्त्र',
    'wings.wing12.head': 'प्रमुख: [नाव]',
    'wings.wing12.motto': 'प्रश्न विचारा. समजून घ्या. कनेक्ट व्हा.',
    'wings.wing12.why': 'मानवी समाज, संस्कृती आणि आपल्या सभोवतालच्या जगाचा शोध घ्या.',
    'wings.wing12.what': 'सामाजिक अभ्यास, तत्त्वज्ञान, इतिहास, मानसशास्त्र आणि सांस्कृतिक चर्चा.',
    'wings.wing12.requirements': 'समाजाबद्दल उत्सुकता, समालोचनात्मक विचार आणि शिकण्याची आवड.',
    'wings.wing12.faq.q': 'प्रश्न: आम्ही कोणत्या विषयांचा समावेश करतो?',
    'wings.wing12.faq.a': 'उत्तर: तत्त्वज्ञान, समाजशास्त्र, इतिहास आणि समकालीन समस्या.',
    'wings.wing13.name': 'पर्यावरणीय कल्याण',
    'wings.wing13.head': 'प्रमुख: [नाव]',
    'wings.wing13.motto': 'संरक्षण करा. टिकवा. भरभराट करा.',
    'wings.wing13.why': 'आपल्या ग्रहाचे रक्षक व्हा आणि पर्यावरणीय जागरूकता वाढवा.',
    'wings.wing13.what': 'टिकाऊपणा, पर्यावरणीय जागरूकता, हरित उपक्रम आणि कल्याण.',
    'wings.wing13.requirements': 'पर्यावरणाची आवड, टिकाऊपणा मानसिकता आणि कृती-आधारित दृष्टीकोन.',
    'wings.wing13.faq.q': 'प्रश्न: कोणत्या प्रकारच्या क्रियाकलाप?',
    'wings.wing13.faq.a': 'उत्तर: वृक्षारोपण मोहिमा, स्वच्छता मोहिमा, जागरूकता मोहिमा आणि बरेच काही.',
    'wings.wing14.name': 'कायदेशीर',
    'wings.wing14.head': 'प्रमुख: [नाव]',
    'wings.wing14.motto': 'जाणून घ्या. संरक्षण करा. नेतृत्व करा.',
    'wings.wing14.why': 'कायदा समजून घ्या आणि समाजात न्यायासाठी आवाज व्हा.',
    'wings.wing14.what': 'कायदेशीर जागरूकता, संवैधानिक मूल्ये, अधिकार आणि कर्तव्ये, आणि कायदेशीर वकिली.',
    'wings.wing14.requirements': 'कायदा, न्याय आणि सामाजिक वकिलीत रुची.',
    'wings.wing14.faq.q': 'प्रश्न: मला कायद्याची पदवी आवश्यक आहे का?',
    'wings.wing14.faq.a': 'उत्तर: नाही, फक्त न्याय आणि कायदेशीर जागरूकतेची आवड!',
    'wings.footer.brand': 'इग्नाइट युथ कम्युनिटी',
    'wings.footer.description': 'नेते, नवप्रवर्तक आणि परिवर्तनकर्त्यांच्या पुढील पिढीला सक्षम करणे.',
    'wings.footer.contact': 'संपर्क करा',
    'wings.footer.follow': 'आम्हाला फॉलो करा',
    'wings.footer.links': 'द्रुत दुवे',
    'wings.footer.home': 'होम',
    'wings.footer.about': 'आमच्याबद्दल',
    'wings.footer.wings': 'विंग्स',
    'wings.footer.gallery': 'गॅलरी',
    'wings.footer.activities': 'आमच्या क्रियाकलाप',
    'wings.footer.join': 'IYC मध्ये सामील व्हा',
    'wings.footer.rights': 'सर्व हक्क राखीव.',
    'wings.footer.tagline': 'युवकांना प्रज्वलित करा. ज्ञान सामायिक करा. नेते बनवा. राष्ट्राची सेवा करा.',
    'wings.footer.instagram': 'इन्स्टाग्राम',
    'wings.footer.youtube': 'यूट्यूब',
    'wings.footer.twitter': 'एक्स (ट्विटर)',
